            raise InvalidInput("priority/dei require tag")
        if (
            not _is_int(ethertype)
            or not 0 <= ethertype <= 0xFFFF
            or ethertype == FRAME_ENCODE_TAG_ETHERTYPE
        ):
            raise InvalidInput("bad ethertype")
        if payload is None:
